import type { ArtifactIndexItem, DatasetEntry, DatasetWindow } from '../../api/types'
import type { StormSpec } from '../../api/stormspec'

/**
 * Historical data → crisis scenario. The observed-analogue presets carry their UTC stress day in
 * their id (`observed-<kind>-YYYY-MM-DD`, packages/stormspec/presets/observed-*.yaml, generated by
 * pipelines/observed); a dataset's published window is linked to the presets listed in its catalog
 * entry (`links.scenario_ids`) whose stress day lies inside the window. Nothing else is assumed:
 * the network, events and results come from the API (scenario records, artifact index).
 */

const STRESS_DAY = /(\d{4}-\d{2}-\d{2})$/
const DAY_MS = 86_400_000

export interface StressLink {
  window: DatasetWindow
  scenarioId: string
  /** The stress day "YYYY-MM-DD" (UTC calendar day). */
  day: string
  /** [start, end) of the stress day in epoch ms (UTC). */
  dayStartMs: number
  dayEndMs: number
}

/** Published windows of `d` paired with the analogue presets whose stress day they contain. */
export function stressLinks(d: Pick<DatasetEntry, 'temporal' | 'links'>): StressLink[] {
  const out: StressLink[] = []
  for (const window of d.temporal?.windows ?? []) {
    const lo = Date.parse(window.start_utc)
    const hi = Date.parse(window.end_utc)
    for (const scenarioId of d.links.scenario_ids) {
      const day = STRESS_DAY.exec(scenarioId)?.[1]
      const start = day ? Date.parse(`${day}T00:00:00Z`) : NaN
      // The window's end is its last covered timestamp, so the stress day starts within [lo, hi].
      if (Number.isFinite(start) && start >= lo && start <= hi) out.push({ window, scenarioId, day: day!, dayStartMs: start, dayEndMs: start + DAY_MS })
    }
  }
  return out
}

export interface AnalogueFacts {
  /** Hourly demand multipliers applied to every load: range and number of hourly events. */
  demand: { min: number; max: number; hours: number } | null
  /** One daily availability multiplier per carrier (carriers without an event keep the network's profile). */
  renewables: { carrier: string; value: number }[]
  /** The 1 January the demand level is relative to, as stated in the preset description. */
  referenceDay: string | null
  /** The detection criterion, as stated in the preset description. */
  criterion: string | null
  /** Snapshots of the scenario horizon. */
  snapshots: number | null
}

/** Facts stated by an analogue preset: its events and its own description; nothing is inferred. */
export function analogueFacts(spec: Pick<StormSpec, 'events' | 'description' | 'horizon'>): AnalogueFacts {
  const demand = spec.events.flatMap((e) => (e.type === 'demand_multiplier' ? [e.value] : []))
  const renewables = spec.events.flatMap((e) => (e.type === 'renewable_availability_multiplier' ? [{ carrier: e.carrier, value: e.value }] : []))
  const text = (spec.description ?? '').replace(/\s+/g, ' ')
  return {
    demand: demand.length ? { min: Math.min(...demand), max: Math.max(...demand), hours: demand.length } : null,
    renewables,
    referenceDay: /reference day (\d{4}-\d{2}-\d{2})/.exec(text)?.[1] ?? null,
    criterion: /detected objectively in [^(]*\(([^()]*(?:\[[^\]]*\][^()]*)?)\)/.exec(text)?.[1] ?? null,
    snapshots: spec.horizon?.snapshots ?? null,
  }
}

/** Unserved energy of a precomputed simulation artifact, as the artifact index reports it. */
export function indexUnservedMwh(items: ArtifactIndexItem[] | undefined, scenarioId: string): number | null {
  const item = items?.find((i) => i.kind === 'simulation' && (i.scenario_id === scenarioId || i.artifact_id === scenarioId))
  const v = item?.unserved_energy_mwh
  return typeof v === 'number' && Number.isFinite(v) ? v : null
}
